INSERT INTO `halamanstatis` (`id_halaman`, `judul`, `judul_seo`, `isi_halaman`, `tgl_posting`, `gambar`, `username`, `dibaca`, `jam`, `hari`) VALUES
(46, 'About Us', 'about-us', '<p>PT OSI began its business operation as a Consultant, Process/Laboratory Instrumentation, Field Instrument and Automation solutions providing company in June 2018</p>\r\n\r\n<p>PT OSI provides one stop solution for field of Process Analyzer, Liquid Analyzer, Laboratory Instrumentation, Field instrumentation and Automation Solutions as a cutting-edge technology company specializing in providing comprehensive instrumentation and automation solutions for a wide range of industries. With a deep commitment to innovation, quality, and customer satisfaction, we empower our clients to optimize their processes, enhance efficiency, and achieve their operational goals.</p>\r\n\r\n<p>PT OSI is focusing exclusively in high quality and cost?effective Analytical system development, Field Device Measurement, Automation and implementation of services. We are advancing on a tremendous pace and with involvement of skilled and experienced people working in the organization. PT OSI is currently doing business with Indonesia Environmental Agency, EPC and Industrial.</p>\r\n', '2014-04-07', '', 'admin', 1088, '13:10:57', 'Senin'),
(53, 'Sejarah Perusahaan', 'sejarah-perusahaan', '<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">Pada 20 Juli 2006, PT Pertamini&nbsp;(Persero) melakukan transformasi fundamental dan usaha Perusahaan. PT Pertamini&nbsp;(Persero) mengubah visi Perusahaan yaitu, &ldquo;Menjadi Perusahaan Minyak Nasional Kelas Dunia&ldquo; pada 10 Desember 2007. Kemudian tahun 2011, Pertamini&nbsp;menyempurnakan visinya, yaitu &ldquo;Menjadi Perusahaan Energi Nasional Kelas Dunia&ldquo;. Melalui RUPSLB tanggal 19 Juli 2012, Pertamini&nbsp;menambah modal ditempatkan/disetor serta memperluas kegiatan usaha Perusahaan.</p>\r\n', '2019-11-08', '', 'admin', 8, '23:30:04', 'Jumat'),
(54, 'Instrumentation', 'instrumentation', '<ul>\r\n	<li>Pressure Measurement</li>\r\n	<li>Temperature Measurement</li>\r\n	<li>Level Measurement</li>\r\n	<li>Flow meter &amp; Flow Computer Solution</li>\r\n	<li>Final Control (Control Valve and Accessories)</li>\r\n	<li>PLC, HMI, and SCADA</li>\r\n	<li>Analyzer &amp; Sampling Systems</li>\r\n</ul>\r\n', '2019-11-09', '', 'admin', 855, '02:03:29', 'Sabtu'),
(60, 'AI POWERED ANALYTICS & PREDICTIVE SOFTWARE', 'ai-powered-analytics--predictive-software', '<h2>Fast track to technical knowledge on critical assets in manufacturing, energy and logistics&nbsp;through&nbsp;reliable AI-Analytics seamlessly integrating&nbsp;client data&nbsp;with our&nbsp;non&nbsp;invasive sensors network</h2>\r\n\r\n<p><strong>GradeSens</strong> enables its clients to&nbsp;fast-track their AI capabilities, unlocking new competitive edges and generating essential&nbsp;technical knowledges.</p>\r\n\r\n<p>With a focus on&nbsp;critical assets,&nbsp;we help clients effectively manage operational risks. Even when assets are covered by a preventive maintenance process, our&nbsp;24/7 AI-enhanced monitoring&nbsp;delivers systemic, forward-looking insights into asset performance.</p>\r\n\r\n<p>Our&nbsp;transparent,&nbsp;engineer-designed analytics&nbsp;empower maintenance and service teams, supporting&nbsp;decision-making&nbsp;while fostering job enrichment.</p>\r\n\r\n<p><img alt=\"\" src=\"https://gradesens.com/wp-content/uploads/2024/05/Technical-Presentation-LYRA-1-e1716892820974.png\" style=\"height:338px; width:800px\" /></p>\r\n\r\n<p>LYRA is a true&nbsp;<strong>wireless data acquisition system</strong>&nbsp;consisting of LYRASens (vibration/temperature), LYRALink (IO-Link and analogue interface for the measurement of the electrical current, temperature and relative shaft vibration) and LYRAGate (gateway with Modbus interface for data transfer in MoonStone) and LYRAMesh</p>\r\n\r\n<p>Our&nbsp;<strong>sub-GHz wireless radio&nbsp;technology</strong>&nbsp;grants for&nbsp;<strong>long reading range</strong>&nbsp;in harsh industrial environments. Its&nbsp;<strong>bi-directional&nbsp;</strong>communication allows to configure and maintain the system&nbsp;<strong>remotely</strong>. The TDMA/FHSS MAC ensures the time synchronisation below 0.1ms between all connected devices so that&nbsp;<strong>structured data</strong>&nbsp;is acquired.</p>\r\n\r\n<p>Data acquired in the gateway LYRAGate is&nbsp;<strong>stored, managed and analysed</strong>&nbsp;in our web-app MoonStone Blue. All LYRA devices can be&nbsp;<strong>remotely</strong>&nbsp;configured.</p>\r\n\r\n<p><img alt=\"\" src=\"https://gradesens.com/wp-content/uploads/2023/09/MoonStone.003-1536x703.jpeg\" style=\"height:458px; width:800px\" /></p>\r\n\r\n<h3>MoonStone Insight&#39;s&nbsp;features</h3>\r\n\r\n<ul>\r\n	<li>Smart Monitoring Cloud Platform used to calculate predefined KPIs for each type of machines using classic or AI-based algorithms</li>\r\n	<li>The KPIs are calculated from data stored in MoonStone Blue or/and from 3rd party data collected by our universal cloud connector &quot;MoonStone Snooper&quot;</li>\r\n	<li>The KPIs are calculated using standard libraries specifically designed for rotating (ventilator, compressor,&hellip;) and linear machines (intralogistics robots, cranes,&hellip;). These libraries are continuously upgraded upon customers requirements.</li>\r\n	<li>The KPIs are automatically calculated periodically and published either in form of a comprehensive pdf reports or digitally over a Restful API.</li>\r\n	<li>MoonStone Insight is self contained in a linux docker allowing to run Jupyter Notebooks on schedule</li>\r\n</ul>\r\n\r\n<p>Contact us for more details..</p>\r\n\r\n<p>&nbsp;</p>\r\n', '2025-07-06', '', 'admin', 655, '22:38:53', 'Minggu'),
(52, 'Vision & Mission', 'vision--mission', '<p>VISION</p>\r\n\r\n<p>Our Vision is to achieve 100% customer satisfaction by delivering quality products and services at an affordable cost.&nbsp;Our forward vision is to strive to become an entity in technology based corporate solutions,&nbsp;capable of demanding unconditional response from the targeted niche. We also believe &nbsp;that for our scope of improvisation. We are growing &nbsp;and would always &nbsp;like to remain on the growing streak</p>\r\n\r\n<p><br />\r\nMISSION</p>\r\n\r\n<p>To achieve the reputation of a quality, &nbsp;high standard &nbsp;&amp; reliable solution&nbsp;to be the premier provider of instrumentation and automation solutions that enable our clients to excel in their industries. We aim to deliver innovative, reliable, and tailored solutions that streamline processes, increase productivity,&nbsp;and drive sustainable growth. for customers in the Indonesia industries</p>\r\n', '2019-11-08', '', 'admin', 852, '23:27:27', 'Jumat'),
(55, 'Voltage by Proxxi', 'voltage-by-proxxi', '<p>VOLTAGE by PROXXI</p>\r\n\r\n<p>Workers are exposed to electrical hazards at work on a daily basis: Proxxi Voltage helps protect them from these hazards. The wristband is not intended to replace any existing safety requirements or processes It is an additional layer of protection, intended to monitor for unexpected changes in their electrical environment</p>\r\n\r\n<p>&nbsp;</p>\r\n', '2019-11-09', 'voltage.jpg', 'admin', 777, '02:05:47', 'Sabtu'),
(56, 'GraceHSP', 'gracehsp', '<p>GraceSense&trade; Hot Spot Monitor (HSM) is a non-conductive temperature monitoring and alarming device that identifies potential hot spots and enables user to predict the failures in electrical equipment.</p>\r\n\r\n<p>Identifying faults before they occur saves money when unplanned outages, service interruptions, and equipment failures are avoided. Plant-wide integration is made simple when the device is connected via MODBUS TCP/IP or Ethernet IP and stand-alone application is made possible with GraceSense&trade; web interface to configure temperature thresholds, monitoring intervals and relay outputs.</p>\r\n\r\n<p>SAFETY BY DESIGN</p>\r\n\r\n<p>&bull; Better Maintenance Planning&mdash;Continuous temperature monitoring and alarming device of electrical equipment identifies electrical hot spots before failures and expensive shutdowns occur.</p>\r\n\r\n<p>&bull; Simple Field Installation&mdash;Non-conductive fiber probes securely piggy-back onto existing bolted connections and potential heat sources such as; busbars, breaker connections, bus ducts, transformers, or any other potential hot spots.</p>\r\n\r\n<p>&bull; Any Voltage&mdash;Non-conductive technology safely applied to any electrical systems. &bull; Reduced Risk&mdash;Ability to monitor and retrieve temperature data of critical inaccessible connections and their associated alarms safely via GraceSense&trade; Web Utility Interface, Ethernet I/P, and MODBUS communication.</p>\r\n', '2019-11-09', 'gracehsm.jpg', 'admin', 870, '02:07:42', 'Sabtu'),
(57, 'Services', 'services', '<p>SYSTEM INTERGATOR</p>\r\n\r\n<ul>\r\n	<li>Analytical, Instrumentation and Control ,Electrical, Engineering Design and Software Engineering</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>PROCUREMENT</p>\r\n\r\n<ul>\r\n	<li>Analyzer Product and Automation</li>\r\n	<li>Field Mesurement (Pressure, Temperature, Level, Flow and Final Control)</li>\r\n	<li>Electrical and Panel Control</li>\r\n	<li>Workstation / Server</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>PROJECT &amp; SERVICES</p>\r\n\r\n<ul>\r\n	<li>Analytical Instrumentation and Consultation</li>\r\n	<li>Process Automation</li>\r\n	<li>Instrumentation</li>\r\n	<li>Control System Integration</li>\r\n	<li>Custom Software Development</li>\r\n	<li>Remote Monitoring and Maintenance</li>\r\n	<li>Electrical and Panel Assembly</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n', '2019-11-09', '', 'admin', 855, '02:08:50', 'Sabtu'),
(58, 'Genie', 'genie', '', '2025-04-10', 'genie.jpg', 'admin', 840, '12:06:22', 'Kamis'),
(59, 'legality', 'legality', '<p><img alt=\"\" src=\"/asset/kcfinder/upload/files/certificate27120.jpg\" style=\"height:613px; width:560px\" /></p>\r\n\r\n<p><img alt=\"\" src=\"/asset/kcfinder/upload/files/certificate71102.jpg\" style=\"height:598px; width:525px\" /></p>\r\n\r\n<p><img alt=\"\" src=\"/asset/kcfinder/upload/files/nib.jpg\" style=\"height:592px; width:519px\" /></p>\r\n\r\n<p><img alt=\"\" src=\"/asset/kcfinder/upload/files/pkplh.jpg\" style=\"height:734px; width:507px\" /></p>\r\n', '2025-04-10', '', 'admin', 804, '19:42:16', 'Kamis');
